void setStatus(LedState s) {
  ledState = s; ledStep = 0; ledTimer = millis();
  switch(s) {
    case ST_SERVER_READY: ledOn = false;
      if(ledPin >= 0) digitalWrite(ledPin, LOW);
      return; case ST_WIFI_SEARCH: case ST_SERVER_CONNECT: case ST_ERROR: case ST_REST: ledOn = true;
      if(ledPin >= 0) digitalWrite(ledPin, LOW);
      return;
  }
}

void updateLED() {
  if(ledPin < 0) return;
  const LedStep *pat = 0; int n = 0;
  switch(ledState) {
    case ST_WIFI_SEARCH: pat = PAT_SEARCH; n = 2; break; case ST_SERVER_CONNECT: pat = PAT_CONNECT; n = 3; break;
    case ST_SERVER_READY: digitalWrite(ledPin, LOW); return; case ST_ERROR: pat = PAT_ERROR; n = 3; break;
    case ST_REST: pat = PAT_REST; n = 1; break;
  }
  if(!pat || n <= 0) return;
  unsigned long d = ledOn ? pat[ledStep].onMs : pat[ledStep].offMs;
  if(millis() - ledTimer >= d) {
    ledOn = !ledOn;
    if(!ledOn) ledStep = (ledStep + 1) % n;
    digitalWrite(ledPin, ledOn ? LOW : HIGH); ledTimer = millis();
  }
}

