String readEeprom(int addr) {
  String s = "";
  for(int i=addr; i<EEPROM_SIZE; i++) { char c = EEPROM.read(i); if(!c) break; s += c; }
  return s;
}

void writeEeprom(int addr, String s) {
  for(int i=0; i<s.length(); i++) EEPROM.write(addr+i, s[i]);
  EEPROM.write(addr+s.length(), 0); EEPROM.commit();
}

uint16_t crc16(String s) {
  uint16_t crc = 0xFFFF;
  for(int i=0; i<s.length(); i++) {
    crc ^= (uint8_t)s[i];
    for(int j=0; j<8; j++) crc = (crc&1) ? (crc>>1)^0xA001 : crc>>1;
  }
  return crc;
}

/* A CRC-guarded string in EEPROM: [crc lo][crc hi][payload][0]. */
bool eepromRead(int addr, String& out) {
  String data = readEeprom(addr+2); uint16_t stored = EEPROM.read(addr) | (EEPROM.read(addr+1)<<8);
  if(data.length() == 0 || stored != crc16(data)) return false;
  out = data; return true;
}

/* Store a CRC-guarded string: the payload first, then its checksum. */
void eepromWrite(int addr, String data) {
  writeEeprom(addr+2, data); EEPROM.write(addr, crc16(data)&0xFF); EEPROM.write(addr+1, (crc16(data)>>8)&0xFF);
  EEPROM.commit();
}

void saveConfig() {
  /* Write format: boardId|serverSuffix|saveStates|4|onlineHost. Only the
     last two octets of the local IP are stored (e.g. "7.104"); the fixed prefix
     comes from DEFAULT_IP. An empty suffix means DEFAULT_IP, so setting the
     default also clears a custom IP. */
  String prefix = serverPrefix(); String suffix = "";
  if(localIp != DEFAULT_IP && localIp.startsWith(prefix)) suffix = localIp.substring(prefix.length());
  eepromWrite(CONFIG_ADDR, boardId + "|" + suffix + "|" + (SAVE_STATES?"1":"0") + "|4|" + onlineHost);
}

void loadConfig() {
  String data;
  localIp = DEFAULT_IP;  /* safe fallback if the stored config is corrupt */ onlineHost = defaultOnlineHost();
  ledPin = LED;
  if(!eepromRead(CONFIG_ADDR, data)) {
    if(readEeprom(CONFIG_ADDR+2).length()) { crcError = 1; logLine("ERROR", "config CRC mismatch - starting fresh"); }
    boardId = String("Hero-") + String("32") + "-" + String((uint32_t)ESP.getEfuseMac()).substring(0, 4);
    localIp = DEFAULT_IP; onlineHost = defaultOnlineHost(); ledPin = LED; saveConfig(); return;
  }
  int p1 = data.indexOf('|'); int p2 = (p1 >= 0) ? data.indexOf('|', p1+1) : -1;
  int p3 = (p2 >= 0) ? data.indexOf('|', p2+1) : -1; int p4 = (p3 >= 0) ? data.indexOf('|', p3+1) : -1;
  if(p1>0 && p2>0) {
    boardId = data.substring(0,p1); String storedIp = data.substring(p1+1,p2);
    /* 3rd field is the retired runtime saveStates flag; 4th field is the config version. */
    String ver = (p3==-1) ? String("") : data.substring(p3+1, (p4==-1) ? data.length() : p4);
    /* v3 stores only the last two octets. v2 stored a full IP: migrate it once.
       Older/corrupt data keeps DEFAULT_IP (the removed tablet IP cannot return). */
    String full = "";
    if(ver == "3" && storedIp.length()) {
      String cand = serverPrefix() + storedIp;
      if(validIpv4(cand)) full = cand;
    } else if(ver == "2" && validIpv4(storedIp) && storedIp.startsWith(serverPrefix())) {
      full = storedIp;
    }
    localIp = full.length() ? full : DEFAULT_IP;
    bool dirty = (ver != "4") || (storedIp.length() && full.length() == 0) || (full == DEFAULT_IP && storedIp.length());
    /* v4 adds onlineHost after the version field. ledPin is fixed by the build. */
    if(ver == "4" && p4 >= 0) {
      int p5 = data.indexOf('|', p4+1); String oh = data.substring(p4+1, (p5==-1) ? data.length() : p5);
      oh.trim(); oh.toLowerCase();
      if(oh.length() == 0) onlineHost = "";
      else if(validHostName(oh)) onlineHost = oh;
      else { onlineHost = defaultOnlineHost(); dirty = true; }
    } else {
      onlineHost = defaultOnlineHost();
      if(ver == "4") dirty = true;
    }
    if(dirty) saveConfig();
  }
}

void saveWifiCreds(String ssid, String pass) {
  String data = ssid + "|" + pass; String cur;
  /* Compare-before-write: EEPROM.commit() blocks, and a boot re-save is common. */
  if(eepromRead(WIFI_CREDS_ADDR, cur) && cur == data) return;
  eepromWrite(WIFI_CREDS_ADDR, data);
}

void loadWifiCreds() {
  String data;
  if(!eepromRead(WIFI_CREDS_ADDR, data)) return;
  int p = data.indexOf('|');
  if(p <= 0) return;
  wifiSsidNew = data.substring(0, p); wifiPassNew = data.substring(p+1); hasNewWifi = true;
}

void clearWifiCreds() {
  for(int i=WIFI_CREDS_ADDR; i<WIFI_CREDS_ADDR+100; i++) EEPROM.write(i, 0);
  EEPROM.commit(); hasNewWifi = false; wifiSsidNew = ""; wifiPassNew = "";
}

void saveLastConn(String ssid, String pass, int kind) {
  if(ssid.length() == 0 || kind < 0 || kind > 1) return;
  if(ssid.length() > 32) ssid = ssid.substring(0, 32);
  if(pass.length() > 64) pass = pass.substring(0, 64);
  String data = ssid + "|" + pass + "|" + String(kind);
  if(LAST_CONN_ADDR + 2 + data.length() + 1 >= EEPROM_SIZE) return;
  /* Compare-before-write: EEPROM.commit() blocks the loop, so skip it when nothing changed. */
  if(data == readEeprom(LAST_CONN_ADDR+2)) {
    uint16_t h = EEPROM.read(LAST_CONN_ADDR) | (EEPROM.read(LAST_CONN_ADDR+1)<<8);
    if(h == crc16(data)) return;
  }
  eepromWrite(LAST_CONN_ADDR, data); lastSsid = ssid; lastPass = pass; lastServer = kind;
}

void loadLastConn() {
  lastSsid = ""; lastPass = ""; lastServer = -1;
  if(LAST_CONN_ADDR + 2 >= EEPROM_SIZE) return;
  String data;
  if(!eepromRead(LAST_CONN_ADDR, data)) return;
  int p1 = data.indexOf('|'); int p2 = (p1 > 0) ? data.indexOf('|', p1+1) : -1;
  if(p1 <= 0 || p2 <= p1) return;
  int k = data.substring(p2+1).toInt();
  if(k < 0 || k > 1) return;
  lastSsid = data.substring(0, p1); lastPass = data.substring(p1+1, p2); lastServer = k;
}

void clearLastConn() {
  for(int i=LAST_CONN_ADDR; i<EEPROM_SIZE && i<LAST_CONN_ADDR+120; i++) EEPROM.write(i, 0);
  EEPROM.commit(); lastSsid = ""; lastPass = ""; lastServer = -1; logLine("NET", "last network forgotten");
}

void rememberWifi() {
  if(WiFi.status() != WL_CONNECTED) return;
  String ssid = WiFi.SSID();
  if(ssid.length() == 0) return;
  String pass = WiFi.psk(); saveWifiCreds(ssid, pass); wifiSsidNew = ssid; wifiPassNew = pass; hasNewWifi = true;
  /* A WiFi-only record (kind 0) makes it the first rejoin candidate next boot. */
  if(lastServer < 0) saveLastConn(ssid, pass, 0);
  else if(lastSsid != ssid || lastPass != pass) saveLastConn(ssid, pass, lastServer);
}

void sendWs(const String& cmd, const String& data) {
  if(!wsConnected) return;
  String msg = "ESP:" + boardId + " SER " + cmd + " " + data; ws.sendTXT(msg);
}

void addServerByKind(int kind) {
  String host = ""; int port = LOCAL_PORT; bool secure = false;
  if(kind == 0) { host = onlineHost; port = ONLINE_PORT; secure = true; }
  else if(kind == 1) { host = localIp; port = LOCAL_PORT; secure = false; }
  if(host.length() == 0 || svrCount >= 4) return;
  /* Never dial the same host twice (e.g. onlineHost == the custom local IP). */
  for(int i=0; i<svrCount; i++) if(servers[i] == host && ports[i] == port) return;
  servers[svrCount] = host; ports[svrCount] = port; ssl[svrCount] = secure; svrCount++;
}

void buildServers() {
  svrCount = 0; wsFailedMask = 0;  /* index-based: a rebuilt list invalidates old failure bits */
  /* A saved custom local IP is an explicit choice: always try it first. */
  if(localIp != DEFAULT_IP) {
    addServerByKind(1); addServerByKind(0); return;
  }
  /* Otherwise keep the last successful kind first, then the other fallback. */
  if(lastServer == 0) addServerByKind(0);
  else if(lastServer == 1) addServerByKind(1);
  if(lastServer != 0) addServerByKind(0);
  if(lastServer != 1) addServerByKind(1);
}

int serverKindOf(String host) {
  if(onlineHost.length() && host == onlineHost) return 0;
  if(host == localIp) return 1;
  return -1;
}

/* Serial input is often a full URL: keep only the host.
   https://Example.com:8443/path?x=1 -> example.com */
String cleanHost(const String& raw) {
  String v = raw; v.trim(); v.toLowerCase(); int p = v.indexOf("://");
  if(p >= 0) v = v.substring(p + 3);
  else if(v.startsWith("https:")) v = v.substring(6);
  else if(v.startsWith("http:")) v = v.substring(5);
  else if(v.startsWith("wss:")) v = v.substring(4);
  else if(v.startsWith("ws:")) v = v.substring(3);
  int cut = v.length(); int a = v.indexOf('/'); if(a >= 0 && a < cut) cut = a;
  a = v.indexOf('?'); if(a >= 0 && a < cut) cut = a; a = v.indexOf('#'); if(a >= 0 && a < cut) cut = a;
  v = v.substring(0, cut); v.trim();
  /* Drop an explicit port: ONLINE_PORT is fixed in the firmware. */
  int c = v.lastIndexOf(':');
  if(c > 0 && v.indexOf(':') == c) {
    String port = v.substring(c + 1); bool digits = port.length() > 0;
    for(size_t i = 0; i < port.length(); i++) if(!isDigit(port[i])) digits = false;
    if(digits) v = v.substring(0, c);
  }
  while(v.endsWith(".")) v = v.substring(0, v.length() - 1);
  return v;
}

/* A plain DNS name: no scheme, path, port, spaces or delimiters. */
bool validHostName(const String& h) {
  if(h.length() == 0 || h.length() > 96) return false;
  if(h[0] == '.' || h[h.length() - 1] == '.') return false;
  for(size_t i = 0; i < h.length(); i++) {
    char c = h[i];
    if(!(isAlphaNumeric(c) || c == '.' || c == '-' || c == '_')) return false;
  }
  return true;
}

/* The builder field may contain a full URL: filter it like the serial command. */
String defaultOnlineHost() {
  String h = cleanHost(String(ONLINE_HOST)); return validHostName(h) ? h : String("");
}

/* Tear down the socket and start a fresh server cycle.
   prefer: 0=online, 1=local, -1=keep the last kind. */
void resetNet(int prefer) {
  wsConnected = false; wsMuteUntil = millis() + 1000;
  if(wsEverInit) { ws.disconnect(); delay(50); }
  wsEverInit = false;
  if(prefer >= 0) lastServer = prefer;
  svrFails = 0; svrRounds = 0; svrIdx = 0;
  netRounds = 0; pushedRounds = 0; lastRounds = 0; savedRounds = 0; defaultRounds = 0;
  backoffUntil = 0; connStart = 0; downSince = millis(); buildServers();
}

/* Reconnect after resetNet(). An empty preferHost uses the first server. */
bool resumeNet(const String& preferHost) {
  if(!wifiReady || WiFi.status() != WL_CONNECTED) {
    wifiReady = false; netState = NET_ACQ; netPhaseStart = millis(); setStatus(ST_WIFI_SEARCH); return false;
  }
  if(preferHost.length()) {
    for(int i = 0; i < svrCount; i++) if(servers[i] == preferHost) { svrIdx = i; break; }
  }
  netState = NET_TRY; netPhaseStart = millis(); connectServer(); return true;
}

/* onlineHost:https://Example.com/path -> onlineHost="example.com".
   An empty value clears the online target (local only). No reboot needed. */
bool applyOnlineHost(const String& raw) {
  String in = raw; in.trim();
  if(in.length() == 0) {
    if(onlineHost.length() == 0) { logLine("ONLINE", "already empty - online server disabled"); return true; }
    String old = onlineHost; onlineHost = ""; saveConfig();
    logLine("ONLINE", old + " -> cleared (online disabled), reconnecting to local"); resetNet(1);
    if(!resumeNet(localIp)) { logLine("ONLINE", "waiting for WiFi before connecting"); return true; }
    return true;
  }
  String host = cleanHost(in);
  if(!validHostName(host)) {
    logLine("ONLINE", "invalid \"" + in + "\" - send onlineHost:https://domain/"); return false;
  }
  if(host == onlineHost) {
    logLine("ONLINE", "already " + host + " - nothing to change"); return true;
  }
  String old = onlineHost; onlineHost = host; saveConfig(); String shown = (in == host) ? host : (in + " -> " + host);
  logLine("ONLINE", (old.length() ? old + " -> " : String("set ")) + shown + " (saved), reconnecting now");
  resetNet(0);
  if(!resumeNet(onlineHost)) { logLine("ONLINE", "waiting for WiFi before connecting"); return true; }
  return true;
}

/* wifi:SSID:PASSWORD -> join and save. The password may contain ':' (kept
   after the first one). Nothing is saved unless the join succeeds. */
bool applyWifi(const String& raw) {
  String s = raw; s.trim();
  if(s.length() == 0) {
    logLine("WIFI", "current " + (WiFi.SSID().length() ? WiFi.SSID() : String("-")) + " ip=" + WiFi.localIP().toString() + " | send wifi:SSID:PASSWORD");
    return false;
  }
  int p = s.indexOf(':');
  if(p <= 0 || p == (int)s.length() - 1) {
    logLine("WIFI", "invalid - send wifi:SSID:PASSWORD"); return false;
  }
  String ssid = s.substring(0, p); String pass = s.substring(p + 1); ssid.trim();
  if(ssid.length() == 0 || ssid.length() > 32 || ssid.indexOf('|') >= 0) {
    logLine("WIFI", "invalid SSID - send wifi:SSID:PASSWORD"); return false;
  }
  if(pass.length() > 64) {
    logLine("WIFI", "invalid password (max 64)"); return false;
  }
  String oldSsid = WiFi.SSID(); String oldPass = WiFi.psk();
  /* Drop the socket before the WiFi swap; the local IP will probably change. */
  resetNet(-1); logLine("WIFI", "joining " + ssid + " ...");
  if(!holdWifi(ssid.c_str(), pass.c_str(), 15000)) {
    logLine("WIFI", "failed (" + wifiStatusLabel(WiFi.status()) + ")");
    /* Never leave the board offline because of a typo: restore the old net. */
    if(oldSsid.length() && holdWifi(oldSsid.c_str(), oldPass.c_str(), 10000)) {
      wifiReady = true; rememberWifi(); logLine("WIFI", "restored " + oldSsid + " ip=" + WiFi.localIP().toString());
      resetNet(-1); resumeNet(""); return false;
    }
    wifiReady = false; netState = NET_ACQ; netPhaseStart = millis(); backoffUntil = millis() + 15000;
    setStatus(ST_WIFI_SEARCH); logLine("WIFI", "no network - searching"); return false;
  }
  wifiReady = true; saveWifiCreds(ssid, pass); wifiSsidNew = ssid; wifiPassNew = pass; hasNewWifi = true;
  rememberWifi(); logLine("WIFI", "connected " + ssid + " ip=" + WiFi.localIP().toString() + " (saved)");
  /* A new network means a new route: restart the server cycle cleanly. */
  resetNet(-1); resumeNet(""); return true;
}

/* boardId:Hero-Kitchen -> ask the server to alias the old ID. The server
   sends SER ESP:<old> BOARD_ID <new>; the existing handler applies it, so
   rooms/nodes/automations keep working. Offline = refused (no alias). */
bool requestBoardId(const String& raw) {
  String next = raw; next.trim();
  if(next.length() == 0) { logLine("ID", "current " + boardId + " | send boardId:Hero-Name"); return false; }
  if(next == boardId) { logLine("ID", "already " + boardId + " - nothing to change"); return true; }
  if(!validBoardId(next)) { logLine("ID", "invalid \"" + next + "\" - use Hero-Name (max 23, letters/digits/-/_/.)"); return false; }
  if(pendingBoardId.length()) { logLine("ID", "waiting for server on " + pendingBoardId + " ..."); return false; }
  if(!wsConnected) {
    logLine("ID", "not connected - connect to the server first (rename needs the server alias)"); return false;
  }
  pendingBoardId = next; pendingBoardIdAt = millis(); sendWs("BOARD_ID", boardId + ":" + next);
  logLine("ID", "requested " + boardId + " -> " + next + " (waiting for server)"); return true;
}

void printHelp() {
  String pre = serverPrefix(); String shortIp = localIp.startsWith(pre) ? localIp.substring(pre.length()) : localIp;
  Serial.println(); Serial.println("Hero serial"); Serial.println("ip:" + shortIp + "  local server");
  Serial.println("onlineHost:<url>  online server"); Serial.println("onlineHost:  online off");
  Serial.println("wifi:<ssid>:<pass>  join WiFi"); Serial.println("boardId:<Hero-Name>  rename");
  Serial.println("?  this list"); Serial.println("id: " + boardId);
  Serial.println("online: " + (onlineHost.length() ? onlineHost : String("-")));
  Serial.println("wifi: " + (WiFi.SSID().length() ? WiFi.SSID() : String("-")));
}

void connectServer() {
  if(!wifiReady) return;
  if(svrIdx >= svrCount) svrIdx = 0;
  /* The attempt clock starts HERE (a stale one fired the rotation instantly). */
  connStart = millis(); backoffUntil = 0; connHost = servers[svrIdx]; connPort = ports[svrIdx];
  setStatus(ST_SERVER_CONNECT);
  /* Log a new target once; repeated retries to the same host are implied by
     the offline line and would only flood the monitor. */
  static String shownHost = ""; static int shownPort = -1;
  if(connHost != shownHost || connPort != shownPort) {
    shownHost = connHost; shownPort = connPort; logLine("SRV", "connecting " + connHost + ":" + String(connPort));
  }
  /* Tear the old socket down first, so the library keeps no half-open socket behind. */
  wsMuteUntil = millis() + 1000;
  if(wsEverInit) { ws.disconnect(); delay(50); }
  wsEverInit = true;
  /* No access token: the sheet carries none, so the board always connects anonymously. */
  ws.setAuthorization("");
  if(ssl[svrIdx]) {
    ws.beginSSL(servers[svrIdx].c_str(), ports[svrIdx], "/ws");
  } else {
    ws.begin(servers[svrIdx].c_str(), ports[svrIdx], "/ws");
  }
      /* The library auto-reconnect is OFF: connectionLoop() is the only authority. */
      ws.setReconnectInterval(0);
}

/* Change the local server at runtime: validate, persist, rebuild the list and
   reconnect without a reboot. Called from the serial monitor (safe: main loop). */
bool applyServerIp(const String& ip) {
  String next = ip; next.trim(); int firstDot = next.indexOf('.'); int lastDot = next.lastIndexOf('.');
  if(firstDot > 0 && firstDot == lastDot) {
    /* "7.104" -> "192.168.7.104": the fixed prefix is added here, never stored. */
    next = serverPrefix() + next;
  } else if(firstDot < 0) {
    logLine("IP", "invalid - send ip:7.104 or a full IP"); return false;
  }
  if(!validIpv4(next)) {
    logLine("IP", "invalid " + next + " - send ip:7.104 or a full IP"); return false;
  }
  String prefix = serverPrefix();
  if(!next.startsWith(prefix)) {
    logLine("IP", "refused - must start with " + prefix); return false;
  }
  if(WiFi.status() == WL_CONNECTED && next == WiFi.localIP().toString()) {
    logLine("IP", "refused - " + next + " is the board's own IP"); return false;
  }
  String old = localIp;
  if(next == localIp) {
    logLine("IP", "already " + next + " - nothing to change"); return true;
  }
  localIp = next; saveConfig();
  logLine("IP", old + " -> " + localIp + ((localIp == DEFAULT_IP) ? " (default, custom cleared)" : " (saved)") + ", reconnecting now");
  resetNet(1);
  if(!resumeNet(localIp)) { logLine("IP", "waiting for WiFi before connecting"); return true; }
  return true;
}

/* Serial monitor commands (ip, onlineHost, wifi, boardId). Works with OR
   without a newline: most serial monitors send a bare string, so a 250 ms
   pause ends the line too. Bounded buffer: a long paste cannot grow the heap. */
void serialCommand() {
  static char buf[128]; static uint8_t len = 0; static unsigned long lastRx = 0; bool lineReady = false;
  /* A rename request is confirmed by the server; do not hang forever. */
  if(pendingBoardId.length() && millis() - pendingBoardIdAt > 5000) {
    logLine("ID", "no server confirmation for " + pendingBoardId + " - still " + boardId); pendingBoardId = "";
  }
  while(Serial.available()) {
    char c = (char)Serial.read(); lastRx = millis();
    if(c == '\r' || c == '\n') { lineReady = true; break; }
    if(len < sizeof(buf) - 1) buf[len++] = c;
  }
  if(!lineReady && len && millis() - lastRx > 250) lineReady = true;
  if(!lineReady) return;
  buf[len] = 0; len = 0; String line(buf); line.trim();
  if(line.length() == 0) return;
  String low = line; low.toLowerCase();
  if(low.startsWith("ip:")) applyServerIp(line.substring(3));
  else if(low == "ip") logLine("IP", "current " + localIp + " | send ip:7.104");
  else if(low.startsWith("onlinehost:")) applyOnlineHost(line.substring(11));
  else if(low == "onlinehost") logLine("ONLINE", onlineHost.length() ? onlineHost : String("off"));
  else if(low.startsWith("wifi:")) applyWifi(line.substring(5));
  else if(low == "wifi") logLine("WIFI", "current " + (WiFi.SSID().length() ? WiFi.SSID() : String("-")) + " ip=" + WiFi.localIP().toString());
  else if(low.startsWith("boardid:")) requestBoardId(line.substring(8));
  else if(low == "boardid") logLine("ID", "current " + boardId);
  else if(low == "help" || low == "?" || low == "!") printHelp();
  else {
    int c = line.indexOf(':'); String head = (c >= 0) ? line.substring(0, c) : line;
    logLine("CMD", "unknown \"" + head + "\" | send ?");
  }
}

bool holdWifi(const char* ssid, const char* pass, unsigned long ms) {
  WiFi.mode(WIFI_STA); WiFi.disconnect();
  /* Transient join: NEVER write these creds to flash (the saved net is the real fixture). */
  WiFi.persistent(false); WiFi.begin(ssid, pass);
  if(waitWifi(ms)) return true;
  /* Stop the core's auto-retry so it cannot fight the next candidate. */
  WiFi.disconnect(); return false;
}

bool waitWifi(unsigned long ms) {
  unsigned long t = millis();
  while(WiFi.status() != WL_CONNECTED && millis() - t < ms) { updateLED(); delay(10); }
  setStatus(WiFi.status() == WL_CONNECTED ? ST_SERVER_CONNECT : ST_WIFI_SEARCH); return WiFi.status() == WL_CONNECTED;
}

/* Join one of the stored nets: 0 = the flash net, 1 = remembered,
   3 = the pushed credentials, 4 = the default WiFi. */
bool wifiJoin(int kind, unsigned long ms) {
  switch(kind) {
    /* Re-join the flash-saved net (WiFi.begin() with no args). */
    case 0: WiFi.mode(WIFI_STA); WiFi.begin(); return waitWifi(ms);
    case 1: if(lastSsid.length() == 0) return false; return holdWifi(lastSsid.c_str(), lastPass.c_str(), ms);
    case 3: if(!hasNewWifi || wifiSsidNew.length() == 0) return false; return holdWifi(wifiSsidNew.c_str(), wifiPassNew.c_str(), ms);
    default: if(!DEFAULT_WIFI_SSID[0]) return false; return holdWifi(DEFAULT_WIFI_SSID, DEFAULT_WIFI_PASS, ms);
  }
}

/* Boot acquisition: saved -> remembered -> pushed -> default.
   Success is reported once by the boot summary; only failures are useful here. */
bool wifiBootAcquire() {
  if(wifiJoin(0, 10000)) { wifiReady = true; rememberWifi(); return true; }
  if(wifiJoin(1, 10000)) { wifiReady = true; rememberWifi(); return true; }
  if(wifiJoin(3, 8000)) { wifiReady = true; rememberWifi(); return true; }
  if(wifiJoin(4, 10000)) { wifiReady = true; rememberWifi(); return true; }
  return false;
}

bool servoSet(String pin, int val) { return false; }
void setRelay(String pin, int val) {
  if(servoSet(pin, val)) return;

  int idx = findPin(pin);
  if(idx == -1) return;
  val = constrain(val,0,255);

  /* Active-Low inversion lives ONLY in the physical drive; the wire stays logical (1 = really ON). */
  bool al = isAlPin(pin);
  if(val <= 1) ledcWrite(outGpio[idx], ((val != 0) ^ al) ? 255 : 0);
  else ledcWrite(outGpio[idx], al ? 255 - val : val);

  /* The stored string carries the :AL suffix, so a reboot re-derives the flag from the same region. */
  String old = getState(pin); setState(pin, String(val) + (al ? ":AL" : ""));
  /* Persist gate (SAVE STATES): the ONLY write of the relay state, and only on a real change. */
  if(saveStates && old != getState(pin)) writeEeprom(RELAY_ADDR, relayStates);
}

void applySavedStates() {
  /* Restore gate (SAVE STATES): OFF means the board starts from the defaults. */
  if(!saveStates) return;
  String saved = readEeprom(RELAY_ADDR);
  if(saved.length()) relayStates = saved;
  /* Re-derive the A-L flags from the persisted values so the initial drive uses the right LEVEL. */
  for(int i=0;i<outCount;i++) {
    String v = getState(outPins[i]);
    if(v.endsWith(":AL")) setAlPin(outPins[i], true);
  }
}

void restoreRelays() {
  applySavedStates();

  for(int i=0; i<outCount; i++) {
    if(isServoPin(outPins[i])) continue;
    String v = getState(outPins[i]);
    if(v.endsWith(":AL")) v = v.substring(0, v.length()-3);
    setRelay(outPins[i], v.length() ? v.toInt() : 0);
  }

  servoRestorePost();
}

String allStates() {
  String r = "";
  for(int i=0; i<outCount; i++) {
    if(i) r += "|";
    r += String(outPins[i]) + ":" + getState(outPins[i]);
  }
  String sx = servoStatesExt();
  if(sx.length()) { if(r.length()) r += "|"; r += sx; }
  return r;
}

void readSensors() {
  static int lastVal[inCount]; static bool have = false; static bool wasConnected = false;
  /* Force-send every sensor once on a fresh connect (the site shows real values instantly). */
  bool freshConnect = (!wasConnected && wsConnected);
  if(freshConnect) have = false;
  for(int i=0; i<inCount; i++) {
    if(isServoPin(inPins[i])) continue;
    bool analog = inPins[i][0]=='A'; int v = analog ? analogRead(inGpio[i]) : digitalRead(inGpio[i]);
    /* A0 floats around 8-9 with nothing wired: that is noise, not a reading. */
    bool silent = strcmp(inPins[i], "A0") == 0 && v < 10;
    if(!silent && (!have || lastVal[i] != v || freshConnect)) {
      if(wsConnected) sendWs("SENSOR", String(inPins[i]) + ":" + v);
    }
    lastVal[i] = v;
  }
  have = true; wasConnected = wsConnected;
}

/* Copy EXACTLY len bytes - a WS frame carries no NUL terminator. The ESP8266
   core has no String(char*, len) constructor, so concat() is the portable way:
   same bytes, no read past the end of the frame. */
String wsText(uint8_t* p, size_t len) {
  String s; s.concat((const char*)p, (unsigned int)len); return s;
}

void wsEvent(WStype_t t, uint8_t* p, size_t len) {
  /* A deliberate socket swap replays teardown events: stay silent for a moment.
     Only DISCONNECTED is muted: CONNECTED and TEXT must always be processed. */
  if(t == WStype_DISCONNECTED && millis() < wsMuteUntil) return;
  /* One offline line per server target until a success re-arms the list. */
  static unsigned long lastOnlineLog = 0;
  switch(t) {
    case WStype_DISCONNECTED: {
      wsConnected = false; setStatus(ST_ERROR); downSince = millis(); int idx = -1;
      for(int i=0; i<svrCount; i++) if(servers[i] == connHost && ports[i] == connPort) { idx = i; break; }
      bool firstForTarget = (idx < 0) || !(wsFailedMask & (1 << idx));
      if(firstForTarget) {
        if(idx >= 0) wsFailedMask |= (1 << idx);
        String why = (p && len) ? wsText(p, len) : String("link closed");
        unsigned long secs = connStart ? (millis() - connStart) / 1000 : 0;
        logLine("SRV", "offline " + connHost + ":" + String(connPort) + " after " + String(secs) + "s - " + why + (why.indexOf("HTTP 3") >= 0 ? " (host needs a public deployment URL)" : ""));
      }
      break;
    }

    case WStype_CONNECTED: {
      wsConnected = true;
      /* A successful session re-arms every target for the next real drop. */
      bool afterDrop = (wsFailedMask != 0); wsFailedMask = 0; svrFails = 0; svrRounds = 0; backoffUntil = 0;
      setStatus(ST_SERVER_READY);
      /* Remember this connection (net + server kind) - flagged here, PERSISTED from the loop. */
      lastConnPending = true;
      if(afterDrop || millis() - lastOnlineLog > 3000) {
        lastOnlineLog = millis();
        logLine("SRV", "online " + connHost + ":" + String(connPort) + " (" + String(connStart ? (millis() - connStart) / 1000 : 0) + "s)");
      }
      sendWs("REGISTER", "-"); sendWs("ALL", allStates()); irAnnounce(); espnowAnnounce();
      if(crcError) { crcError=0; sendWs("STORAGE","CRC_ERROR"); }
      break;
    }

    case WStype_TEXT: {
      if(!p || !len) break;
      /* Copy EXACTLY len bytes — the frame is not NUL-terminated. */
      String msg = wsText(p, len);
      /* A rename reply may arrive addressed to the old or the new id. */
      bool forMe = msg.startsWith("SER ESP:" + boardId);
      if(!forMe && pendingBoardId.length()) forMe = msg.startsWith("SER ESP:" + pendingBoardId + " ");
      if(!forMe) break;

      int start = msg.indexOf(' ', 4) + 1; int sp = msg.indexOf(' ', start); String cmd = msg.substring(start, sp);
      String data = (sp == -1) ? "" : msg.substring(sp+1);

      if(cmd=="GET" && data=="ALL") sendWs("ALL", allStates());
      /* SAVE_STATES is a build-time #define now: EEPROM can no longer re-enable
         state saving. The command only clears an old snapshot when asked OFF. */
      else if(cmd=="SAVE_STATE") {
        bool on = (data == "1" || data == "true");
        if(!on) eepromWrite(RELAY_ADDR, "");
        logLine("CFG", String("saveStates=") + String(SAVE_STATES ? "1" : "0") + " (build-time; SAVE_STATE ignored)");
      }
      /* STATUS is a liveness probe; LOCAL_MODE is a retired feature. */
      else if(cmd=="STATUS" || cmd=="LOCAL_MODE") { }
      else if(cmd=="SET") {
        /* data = "<pin>:<val>", optionally suffixed ":AL" (Active-Low runtime flag). */
        String pv = data; bool isAL = false;
        if(pv.endsWith(":AL")) { isAL = true; pv = pv.substring(0, pv.length()-3); }
        int c = pv.indexOf(':');
        if(c<1) break;
        String pin=pv.substring(0,c), val=pv.substring(c+1);
        /* The IR blaster/receiver are not manual-output pins: refuse loudly. */
        if(pinReserved(pin)) {
          logLine("ERROR", "SET " + pin + " refused (IR reserved pin)"); sendWs("ERROR", "PIN_RESERVED " + pin);
          break;
        }
        if(findPin(pin)==-1 && findServo(pin.c_str())==-1) {
          logLine("ERROR", "SET unknown pin " + pin); break;
        }
        /* Active-Low is meaningless for servo pins — ignore the suffix there. */
        if(findServo(pin.c_str()) != -1) isAL = false;
        logLine("CMD", "SET " + pin + ":" + val + (isAL ? ":AL" : "")); setAlPin(pin, isAL);
        setRelay(pin, val.toInt()); sendWs("STATE", pin+":"+val+(isAlPin(pin) ? ":AL" : ""));
      }
      else if(cmd=="SERVO_CFG") {
        if(data.length()) logLine("CMD", "SERVO_CFG " + data);
        applyServoConfig(data);
      }
      else if(cmd=="BOARD_ID") {
        if(validBoardId(data)) {
          if(data != boardId) {
            String old = boardId; boardId = data; pendingBoardId = ""; saveConfig();
            logLine("ID", old + " -> " + boardId + " (server alias applied)");
            logLine("ID", "reboot to update the OTA/mDNS hostname"); sendWs("REGISTER", "-");
          } else {
            pendingBoardId = ""; logLine("ID", "already " + boardId + " - nothing to change");
          }
        } else {
          pendingBoardId = ""; logLine("ID", "server sent invalid id \"" + data + "\" - ignored");
        }
      }
      else if(cmd=="BOARD_ID_ERR") {
        pendingBoardId = ""; logLine("ID", "rename refused: " + data);
      }
      else if(cmd=="LOCAL_IP") {
        if(!validIpv4(data) || !data.startsWith(serverPrefix())) logLine("IP", "invalid " + data + " from app");
        else if(data!=localIp) { logLine("IP", data + " from app - rebooting to apply"); localIp=data; saveConfig(); ESP.restart(); }
      }
      else if(cmd=="WIFI_CREDS") {
        /* data = "ssid password" - the JOIN is done by the loop, never inside this callback. */
        int wp = data.indexOf(' '); String newSsid = (wp == -1) ? data : data.substring(0, wp);
        String newPass = (wp == -1) ? "" : data.substring(wp + 1);
        if(newSsid.length() > 0) {
          /* Identical creds -> do NOT reconnect. */
          bool sameSsid = (newSsid == wifiSsidNew); bool samePass = (newPass == wifiPassNew);
          if(sameSsid && samePass && WiFi.status() == WL_CONNECTED) {
            break;
          }
          /* Never print the password: the SSID is enough to identify the push. */
          logLine("CMD", "WIFI_CREDS ssid=" + newSsid); saveWifiCreds(newSsid, newPass);
          wifiSsidNew = newSsid; wifiPassNew = newPass; hasNewWifi = true; wifiPushPending = true; wifiReady = false;
          netState = NET_ACQ; netPhaseStart = millis(); backoffUntil = 0;
          logLine("NET", "WiFi push queued (ssid=" + newSsid + ")");
        }
      }
      else if(cmd=="IR_SEND") {
        /* Honest ACK: IR_SENT only after a real transmission, IR_ERROR on failure. */
        sendWs(irSendCode(data) > 0 ? "IR_SENT" : "IR_ERROR", "-");
      }
      else if(cmd=="IR_LEARN") {
        if(data.length()) irLearnCmd(data);
      }
      else if(cmd=="ESPNOW_SEND") {
        /* Downlink relay: "<nodeId> <type> <action> <target> <value>". */
        if(data.length()) { logLine("CMD", "ESPNOW_SEND " + data); espnowSendCommand(data); }
      }
      else {
        logLine("ERROR", "unknown cmd=" + cmd);
      }
      break;
    }

    default:
      /* Ping/pong and library internals are normal traffic: never log them. */
      break;
  }
}

void netTransition(NetState ns, const char* reason) {
  (void)reason;  /* state changes are already explained by the NET/SRV lines */ if(ns == netState) return;
  netState = ns; netPhaseStart = millis();
}

void startOTA() {
  if(otaStarted) return;
  if(!wifiReady || WiFi.status() != WL_CONNECTED) return;
  /* Release the mDNS claim so ArduinoOTA can register its own _arduino._tcp service. */
  MDNS.end(); delay(50);
  if(MDNS.begin(boardId.c_str())) {
    ArduinoOTA.setHostname(boardId.c_str()); ArduinoOTA.begin(); otaStarted = true;
    logLine("OTA", "ready at " + boardId + ".local (" + WiFi.localIP().toString() + ")");
  } else {
    if(!otaFailLogged) { otaFailLogged = true; logLine("OTA", "mDNS failed - retrying"); }
  }
}

/* A candidate joined: reset the acquisition cycle and dial the server. */
void acqOk(const char* tag, const char* reason) {
  savedRounds = lastRounds = pushedRounds = defaultRounds = netRounds = 0; svrFails = 0; svrRounds = 0;
  wsFailedMask = 0;  /* fresh WiFi: let each server report its own drop again */ backoffUntil = 0; wifiReady = true;
  rememberWifi(); setStatus(ST_SERVER_CONNECT);
  logLine("NET", "WiFi OK (" + String(tag) + ") ip=" + WiFi.localIP().toString()); netTransition(NET_TRY, reason);
  connectServer();
}

/* One acquisition pass over the WiFi candidates:
   0) a live push from the server (newest user intent, first),
   1) the saved net (flash),
   2) the remembered last connection (EEPROM),
   3) the pushed credentials (from the app),
   4) the default WiFi baked into this build.
   No hotspot scan and no extra join. */
void netAcquire() {
  enum { WF_ALWAYS, WF_REMEMBERED, WF_PUSHED, WF_DEFAULT };
  struct Cand { const char* tag; const char* reason; int kind; unsigned long waitMs; byte* rounds; uint8_t need; };
  static Cand cands[4] = {
    { "saved",      "saved_ok",      0, 10000,   &savedRounds,  WF_ALWAYS },
    { "remembered", "remembered_ok", 1, 10000, &lastRounds,  WF_REMEMBERED },
    { "pushed",     "pushed_ok",     3, 8000,  &pushedRounds, WF_PUSHED },
    { "default",    "default_ok",    4, 10000, &defaultRounds, WF_DEFAULT }
  };
  /* 0) A live push from the server: joined HERE, never in the callback. */
  if(wifiPushPending) {
    wifiPushPending = false;
    if(wifiJoin(3, 8000)) { acqOk("pushed", "pushed_ok"); return; }
    logLine("NET", "WiFi pushed failed (ssid=" + wifiSsidNew + ")"); backoffUntil = millis() + 15000; return;
  }
  for(int i = 0; i < 4; i++) {
    Cand &c = cands[i]; String ssid;
    switch(c.need) {
      case WF_REMEMBERED: if(lastSsid.length() == 0) continue; ssid = lastSsid; break;
      case WF_PUSHED:   if(!hasNewWifi || wifiSsidNew.length() == 0) continue; ssid = wifiSsidNew; break;
      case WF_DEFAULT:  if(!DEFAULT_WIFI_SSID[0]) continue; ssid = String(DEFAULT_WIFI_SSID); break;
    }
    byte n = ++(*c.rounds);
    if(n > 2) { *c.rounds = 0; logLine("NET", "WiFi " + String(c.tag) + " exhausted"); continue; }
    setStatus(ST_WIFI_SEARCH);
    if(!wifiJoin(c.kind, c.waitMs)) {
      logLine("NET", "WiFi " + String(c.tag) + " failed" + (ssid.length() ? (" (ssid=" + ssid + ")") : ""));
      backoffUntil = millis() + 15000; return;
    }
    acqOk(c.tag, c.reason); return;
  }
  /* Recovery: two failed rounds, then a five-minute rest. */
  if(++netRounds >= 2) { netRounds = 0; backoffUntil = millis() + 300000; }
  else { backoffUntil = millis() + 15000; }
  setStatus(ST_WIFI_SEARCH);
}

/* NET_TRY: dial the current server. A full cycle of failures rests for
   5 minutes after 2 cycles. */
void netTry(bool wifiUp) {
  if(wsConnected) { netTransition(NET_READY, "handshake_ok"); return; }
  if(!wifiUp) { wifiReady = false; downSince = millis(); backoffUntil = millis() + 15000; logLine("NET", "WiFi lost - searching"); netTransition(NET_ACQ, "wifi_lost"); return; }
  unsigned long tmo = ssl[svrIdx] ? 9000 : 8000;
  if(millis() - connStart > tmo) {
    if(++svrFails >= 2) {
      svrFails = 0; ++svrIdx;
      if(svrIdx >= svrCount) {
        svrIdx = 0;
        if(++svrRounds >= 2) {
          svrRounds = 0; backoffUntil = millis() + 300000; logLine("SRV", "no server after 2 rounds - pausing 5 min");
          netTransition(NET_ACQ, "server_rest"); setStatus(ST_REST); return;
        }
      }
    }
    connectServer();
  }
}

/* NET_READY: the link is up. Watch it; never switch to another server. */
void netReady(bool wifiUp) {
  if(!wsConnected) {
    downSince = millis();
    /* A session that stayed up long enough proves the server is healthy. */
    if(millis() - connStart >= 30000) svrFails = 0;
    else if(++svrFails >= 2) {
      svrFails = 0; ++svrIdx;
      if(svrIdx >= svrCount) {
        svrIdx = 0;
        if(++svrRounds >= 2) {
          svrRounds = 0; backoffUntil = millis() + 300000; logLine("SRV", "no server after 2 rounds - pausing 5 min");
          netTransition(NET_ACQ, "server_rest"); setStatus(ST_REST); return;
        }
      }
    }
    netTransition(NET_TRY, "disconnected"); connectServer(); return;
  }
  if(!wifiUp) { wifiReady = false; downSince = millis(); backoffUntil = millis() + 15000; logLine("NET", "WiFi lost - searching"); netTransition(NET_ACQ, "wifi_lost"); return; }
}

void connectionLoop() {
  bool wifiUp = (WiFi.status() == WL_CONNECTED); long freeHeap = (long)ESP.getFreeHeap();
  /* Remember the last good connection (deferred from wsEvent). */
  if(wsConnected && lastConnPending) {
    lastConnPending = false; int kind = serverKindOf(connHost);
    if(kind >= 0 && WiFi.SSID().length() > 0) saveLastConn(WiFi.SSID(), WiFi.psk(), kind);
  }
  /* Memory: stay silent unless the board is genuinely about to die. */
  if(millis() - lastHeapLog > 30000) {
    lastHeapLog = millis();
    if(freeHeap < 2048) heapBadWins++; else heapBadWins = 0;
    if(heapBadWins >= 3) {
      logLine("ERR", "memory critical (free=" + String(freeHeap) + ") - restarting");
      if(wsConnected) sendWs("HEAP_LOW", "restarting");
      delay(200); ws.loop(); ESP.restart();
    }
  }
  /* Rest: while disconnected, two rounds are followed by a five-minute pause.
     WiFi down is still a search, not a rest. */
  if(netState != NET_READY && millis() < backoffUntil) { setStatus(wifiUp ? ST_REST : ST_WIFI_SEARCH); return; }
  switch(netState) {
    case NET_ACQ: if(wifiUp && !wifiReady) wifiReady = true;
      if(wifiUp && wifiReady) { svrIdx = 0; netTransition(NET_TRY, "wifi_ready"); connectServer(); break; }
      if(millis() < backoffUntil) break;
      netAcquire(); break; case NET_TRY:   netTry(wifiUp); break; case NET_READY: netReady(wifiUp); break;
  }
}

void setup() {
  Serial.begin(115200); EEPROM.begin(EEPROM_SIZE); analogReadResolution(10); randomSeed(esp_random() ^ micros());
  loadConfig(); servoBoot(); espnowBoot();
  /* Parse the persisted states + A-L flags FIRST, so the initial drive uses the right LEVEL. */
  applySavedStates();
  logLine("BOOT", boardId + " | server " + localIp + (localIp == DEFAULT_IP ? " (default)" : " (saved)") + " | saveStates " + String(saveStates ? "ON" : "OFF") + " | ? for commands");
  if(ledPin >= 0) { pinMode(ledPin, OUTPUT); digitalWrite(ledPin, HIGH); }
  for(int i=0;i<outCount;i++) { if(isServoPin(outPins[i])) continue; pinMode(outGpio[i], OUTPUT); digitalWrite(outGpio[i], isAlPin(outPins[i]) ? HIGH : LOW); ledcAttach(outGpio[i], 5000, 8); ledcWrite(outGpio[i], isAlPin(outPins[i]) ? 255 : 0); }
  for(int i=0;i<inCount;i++) pinMode(inGpio[i], isServoPin(inPins[i]) ? OUTPUT : INPUT);
  restoreRelays();
  /* Instant power-on life: first search pulse fires immediately after pins */
  if(ledPin >= 0) digitalWrite(ledPin, LOW);
  ledOn = true; ledTimer = millis(); setStatus(ST_WIFI_SEARCH);
  WiFi.mode(WIFI_STA); WiFi.persistent(true); WiFi.setAutoReconnect(true); WiFi.setSleep(false); loadWifiCreds();
  loadLastConn();
  /* Boot: auto-join first, then the stored nets through wifiBootAcquire(). */
  savedRounds = 0;
  if(WiFi.status() == WL_CONNECTED) {
    netState = NET_ACQ; netPhaseStart = millis(); wifiReady = true; savedRounds = 0; rememberWifi();
    setStatus(ST_SERVER_CONNECT);
  }
  if(!wifiReady) {
    netState = NET_ACQ; netPhaseStart = millis(); wifiBootAcquire();
  }
  unsigned long startWait = millis();
  while(WiFi.status() != WL_CONNECTED && millis() - startWait < 10000) {
    updateLED(); delay(10);
  }
  if(WiFi.status() == WL_CONNECTED) {
    wifiReady = true; rememberWifi(); setStatus(ST_SERVER_CONNECT);
    logLine("NET", "WiFi OK ssid=" + WiFi.SSID() + " ip=" + WiFi.localIP().toString());
  } else {
    wifiReady = false; setStatus(ST_ERROR); backoffUntil = millis() + 300000;
    logLine("NET", "WiFi failed (" + String(wifiStatusLabel(WiFi.status())) + ") - will keep searching");
  }
  server.begin(); startOTA(); ws.onEvent(wsEvent); ws.setReconnectInterval(0); buildServers(); lastHeapLog = millis();
  netState = wifiReady ? NET_TRY : NET_ACQ;
  if(wifiReady) { svrIdx = 0; connectServer(); }
}

void loop() {
  serialCommand(); ws.loop(); if(otaStarted) ArduinoOTA.handle(); updateLED(); connectionLoop(); if(!otaStarted) startOTA();
  if(millis()-lastSensor>200){ lastSensor = millis(); readSensors(); }
  irLoop();
}

